package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/employees") public class EmployeeController{private final JdbcClient db;private final PasswordEncoder passwords;public EmployeeController(JdbcClient db,PasswordEncoder passwords){this.db=db;this.passwords=passwords;}public record Employee(UUID id,UUID branchId,String branchName,String name,String username,String employeeType,String jobRole,LocalDate dateOfJoining,BigDecimal hourlyRate,BigDecimal monthlySalary,boolean active){}public record Create(@NotNull UUID branchId,@NotBlank String name,@NotBlank String username,@Size(min=8)String password,@Pattern(regexp="OWNER|USER")String employeeType,@Pattern(regexp="OWNER|MANAGER|COUNTER|CHEF|DELIVERY|SERVICE")String jobRole,@NotNull LocalDate dateOfJoining,@DecimalMin("0")BigDecimal hourlyRate,@DecimalMin("0")BigDecimal monthlySalary){}
 @GetMapping List<Employee> list(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);return db.sql("select e.id,e.branch_id,b.name branch_name,e.name,u.username,e.employee_type,e.job_role,e.date_of_joining,e.hourly_rate,e.monthly_salary,e.active from amcservice.employees e join amcservice.branches b on b.id=e.branch_id left join amcservice.users u on u.id=e.user_id where e.tenant_id=:t order by e.active desc,b.name,e.name").param("t",u.tenantId()).query(Employee.class).list();}
 @PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") @ResponseStatus(HttpStatus.CREATED) @Transactional Employee create(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody Create r){CustomerController.tenant(u);var branch=db.sql("select name from amcservice.branches where id=:b and tenant_id=:t and active").param("b",r.branchId()).param("t",u.tenantId()).query(String.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Branch not found"));var userId=UUID.randomUUID();var employeeId=UUID.randomUUID();var role="OWNER".equals(r.employeeType())?"OWNER":"EMPLOYEE";try{db.sql("insert into amcservice.users(id,tenant_id,branch_id,username,password_hash,display_name,role) values(:id,:t,:b,:username,:password,:name,:role)").param("id",userId).param("t",u.tenantId()).param("b",r.branchId()).param("username",r.username()).param("password",passwords.encode(r.password())).param("name",r.name()).param("role",role).update();}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"User ID already exists");}db.sql("insert into amcservice.employees(id,tenant_id,branch_id,user_id,name,employee_type,job_role,date_of_joining,hourly_rate,monthly_salary) values(:id,:t,:b,:u,:name,:type,:job,:joining,:rate,:salary)").param("id",employeeId).param("t",u.tenantId()).param("b",r.branchId()).param("u",userId).param("name",r.name()).param("type",r.employeeType()).param("job",r.jobRole()).param("joining",r.dateOfJoining()).param("rate",r.hourlyRate()).param("salary",r.monthlySalary()).update();db.sql("update amcservice.users set employee_id=:e where id=:u").param("e",employeeId).param("u",userId).update();return new Employee(employeeId,r.branchId(),branch,r.name(),r.username(),r.employeeType(),r.jobRole(),r.dateOfJoining(),r.hourlyRate(),r.monthlySalary(),true);}
 public record Update(@NotNull UUID branchId,@NotBlank String name,@Pattern(regexp="OWNER|USER")String employeeType,@Pattern(regexp="OWNER|MANAGER|COUNTER|CHEF|DELIVERY|SERVICE")String jobRole,@NotNull LocalDate dateOfJoining,@DecimalMin("0")BigDecimal hourlyRate,@DecimalMin("0")BigDecimal monthlySalary,boolean active,@Size(min=8)String newPassword){}
 @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") @Transactional Employee update(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@Valid @RequestBody Update r){CustomerController.tenant(u);var branch=db.sql("select name from amcservice.branches where id=:b and tenant_id=:t").param("b",r.branchId()).param("t",u.tenantId()).query(String.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Branch not found"));var userId=db.sql("select user_id from amcservice.employees where id=:id and tenant_id=:t").param("id",id).param("t",u.tenantId()).query(UUID.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));db.sql("update amcservice.employees set branch_id=:b,name=:name,employee_type=:type,job_role=:job,date_of_joining=:joining,hourly_rate=:rate,monthly_salary=:salary,active=:active where id=:id and tenant_id=:t").param("b",r.branchId()).param("name",r.name()).param("type",r.employeeType()).param("job",r.jobRole()).param("joining",r.dateOfJoining()).param("rate",r.hourlyRate()).param("salary",r.monthlySalary()).param("active",r.active()).param("id",id).param("t",u.tenantId()).update();var role="OWNER".equals(r.employeeType())?"OWNER":"EMPLOYEE";db.sql("update amcservice.users set branch_id=:b,display_name=:name,role=:role,active=:active where id=:u").param("b",r.branchId()).param("name",r.name()).param("role",role).param("active",r.active()).param("u",userId).update();if(r.newPassword()!=null&&!r.newPassword().isBlank())db.sql("update amcservice.users set password_hash=:p where id=:u").param("p",passwords.encode(r.newPassword())).param("u",userId).update();var username=db.sql("select username from amcservice.users where id=:u").param("u",userId).query(String.class).single();return new Employee(id,r.branchId(),branch,r.name(),username,r.employeeType(),r.jobRole(),r.dateOfJoining(),r.hourlyRate(),r.monthlySalary(),r.active());}
}
